void ceph_put_snap_realm ( struct ceph_mds_client * mdsc , struct ceph_snap_realm * realm ) { dout ( "put_snap_realm %llx %p %d ->%d\n" , realm -> ino , realm , atomic_read ( & realm -> nref ) , atomic_read ( & realm -> nref ) - 1 ) ; if ( down_write_trylock ( & mdsc -> snap_rwsem ) ) { __destroy_snap_realm ( mdsc , realm ) ; up_write ( & mdsc -> snap_rwsem ) ; } else { spin_lock ( & mdsc -> snap_empty_lock ) ; list_add ( & realm -> empty_item , & mdsc -> snap_empty ) ; spin_unlock ( & mdsc -> snap_empty_lock ) ; } } 